import './App.css';

import { useSmartNumpad } from 'react-smart-numpad';

function App() {
  const { value, onChange, onKeyDown } = useSmartNumpad('', { commaDecimal: true });

  return (
    <div className="App">
      <h2>smart-numpad test</h2>
      <input value={value} onChange={onChange} onKeyDown={onKeyDown} />
    </div>
  );
}

export default App;
